property.value:
//VARIABLE_DEF[
    ancestor::SLIST
    and not(ancestor::RESOURCE)
    and (
        ./TYPE/IDENT[
            @text='InputStream' or @text='OutputStream' or
            @text='FileInputStream' or @text='FileOutputStream' or
            @text='BufferedInputStream' or @text='BufferedOutputStream' or
            @text='Reader' or @text='Writer' or
            @text='BufferedReader' or @text='BufferedWriter' or
            @text='FileReader' or @text='FileWriter' or
            @text='PreparedStatement' or @text='ResultSet' or
            @text='Socket' or @text='ServerSocket'
        ]
        or (
            ./TYPE/IDENT[@text='Connection']
            and not(ancestor::COMPILATION_UNIT/IMPORT/DOT[./IDENT[@text='Connection'] and .//IDENT[@text='jsoup']])
        )
        or (
            ./TYPE/IDENT[@text='Statement']
            and not(ancestor::COMPILATION_UNIT/IMPORT/DOT[./IDENT[@text='Statement'] and (.//IDENT[@text='jsqlparser'] or .//IDENT[@text='jena'])])
        )
    )
]

//LITERAL_CATCH[
    PARAMETER_DEF/IDENT[@text = ('e','ex','t','e1','e2','error','exception','exp','err','throwable','exc')]
    and not(
        .//METHOD_CALL[
            (
                .//IDENT[starts-with(@text,'log')]
                or .//IDENT[starts-with(@text,'LOG')]
                or .//IDENT[starts-with(@text,'logger')]
                or .//IDENT[starts-with(@text,'Logger')]
            )
            and ELIST/EXPR/IDENT[@text = ('e','ex','t','e1','e2','error','exception','exp','err','throwable','exc')]
        ]
    )
]
